/** The /preset command, inserted before the exit handler that follows it. */
const INSERT_ANCHOR = "\t\tconst exitHandler = () => {";
const INSERT_CODE = "\t\t// /new -- start a new conversation.\n\t\t//\n\t\t// A session cannot replace itself while it is running, and this deployment\n\t\t// puts the previous one back after an unexpected restart (the harness ends on\n\t\t// its own every few minutes on this platform). So the request is recorded\n\t\t// where the launcher looks for it and the next start comes up empty. The\n\t\t// marker survives an exit, which is what makes /exit straight after it do\n\t\t// what the user means.\n\t\tcommandCtx.commands.register({\n\t\t\tname: \"new\",\n\t\t\tdescription: \"开一个新会话（输入 /exit 立即生效）\",\n\t\t\thandler: () => {\n\t\t\t\ttry {\n\t\t\t\t\twriteFileSync(dshHomePath(\".new-session\"), `${Date.now()}\\n`);\n\t\t\t\t\tappendNotice(\"已记为下次启动开新会话，输入 /exit 立即生效（历史会话用 /resume 选择）\", \"info\");\n\t\t\t\t} catch (error) {\n\t\t\t\t\tappendNotice(`无法记录新会话请求：${error?.message ?? error}`, \"error\");\n\t\t\t\t}\n\t\t\t\treturn { kind: \"success\" };\n\t\t\t}\n\t\t});\n\t\t// /preset -- list presets or switch this session onto one.\n\t\t//\n\t\t// @deepseek-ai/dsh-agent-presets allows a session to change preset only\n\t\t// while it is blank: once a turn has started the composition is mounted\n\t\t// (its docs: \"A session may still change preset while it is blank, and the\n\t\t// effect of that change outlives the blank window\"), and `select` then\n\t\t// throws `agent-preset/locked`. So a locked session degrades to writing a\n\t\t// marker file the launcher honours at the next start -- a preset change\n\t\t// outliving the process is the only thing left that can work, and it beats\n\t\t// telling the user to reinstall or to ask me to re-patch a file.\n\t\tconst currentAgentPreset = () => {\n\t\t\ttry {\n\t\t\t\treturn ctx.get(\"sessionProjections\")?.snapshot(agent.session)?.values?.agentPreset ?? null;\n\t\t\t} catch {\n\t\t\t\treturn null;\n\t\t\t}\n\t\t};\n\t\tconst presetFiber = agent.ctx.inject([\"agentPresets\", \"commands\"], (presetCtx) => {\n\t\t\tpresetCtx.commands.register({\n\t\t\t\tname: \"preset\",\n\t\t\t\tdescription: \"查看或切换预设（未开跑的会话可原地切换）\",\n\t\t\t\tinput: {\n\t\t\t\t\thint: \"[id]\"\n\t\t\t\t},\n\t\t\t\thandler: async ({ rawInput }) => {\n\t\t\t\t\tconst service = presetCtx.agentPresets;\n\t\t\t\t\tconst wanted = (rawInput ?? \"\").trim();\n\t\t\t\t\tif (wanted === \"\") {\n\t\t\t\t\t\tconst roster = await service.list();\n\t\t\t\t\t\tconst current = currentAgentPreset();\n\t\t\t\t\t\tconst rows = roster.map((preset) => {\n\t\t\t\t\t\t\tconst marks = [];\n\t\t\t\t\t\t\tif (preset.id === current) marks.push(\"当前\");\n\t\t\t\t\t\t\tif (preset.id === service.defaultId) marks.push(\"默认\");\n\t\t\t\t\t\t\tif (preset.broken !== void 0) marks.push(\"不可用\");\n\t\t\t\t\t\t\tconst name = preset.name === void 0 ? \"\" : `（${preset.name}）`;\n\t\t\t\t\t\t\treturn `  ${preset.id}${name}${marks.length === 0 ? \"\" : `  [${marks.join(\" / \")}]`}`;\n\t\t\t\t\t\t});\n\t\t\t\t\t\tappendNotice(`预设：\\n${rows.join(\"\\n\")}\\n用法：/preset <id>`, \"info\");\n\t\t\t\t\t\treturn { kind: \"success\" };\n\t\t\t\t\t}\n\t\t\t\t\ttry {\n\t\t\t\t\t\tconst id = await service.select(agent, wanted);\n\t\t\t\t\t\tappendNotice(`预设已切换为 ${id}，本轮起生效。`, \"info\");\n\t\t\t\t\t\treturn { kind: \"success\" };\n\t\t\t\t\t} catch (error) {\n\t\t\t\t\t\tconst text = String(error?.message ?? error);\n\t\t\t\t\t\tif (text.includes(\"already started\") || text.includes(\"locked\")) {\n\t\t\t\t\t\t\ttry {\n\t\t\t\t\t\t\t\twriteFileSync(dshHomePath(\".pending-preset\"), `${wanted}\\n`);\n\t\t\t\t\t\t\t\tappendNotice(`本会话已开跑，预设已锁定。已记为下次启动生效：${wanted}\\n输入 /exit，重启后即以该预设开新会话。`, \"warning\");\n\t\t\t\t\t\t\t} catch (writeError) {\n\t\t\t\t\t\t\t\tappendNotice(`切换预设失败：${text}`, \"error\");\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\treturn { kind: \"success\" };\n\t\t\t\t\t\t}\n\t\t\t\t\t\tappendNotice(`切换预设失败：${text}`, \"error\");\n\t\t\t\t\t\treturn { kind: \"success\" };\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t});\n\t\t});\n";

/** Both disposal sites dispose the TUI's fibers together. */
const DISPOSAL_FROM = "commandFiber.dispose(), fileReferencePromptFiber.dispose()";
const DISPOSAL_TO = "commandFiber.dispose(), fileReferencePromptFiber.dispose(), presetFiber.dispose()";

const [input, output] = process.argv.slice(2);
if (input === undefined || output === undefined) {
	process.stderr.write("usage: patch-tui-zh.mjs <input index.js> <output index.js>\n");
	process.exit(2);
}

let source = readFileSync(input, "utf8");
const failures = [];
let applied = 0;

for (const entry of TABLE) {
	const count = source.split(entry.from).length - 1;
	if (count !== entry.expect) {
		failures.push(`  ${JSON.stringify(entry.from.slice(0, 90))}: 期望 ${entry.expect} 处，实际 ${count} 处`);
		continue;
	}
	source = source.split(entry.from).join(entry.to);
	applied += 1;
}

for (const { id, from, to, expect } of [
	{ id: "insert /preset", from: INSERT_ANCHOR, to: null, expect: 1 },
	{ id: "dispose presetFiber", from: DISPOSAL_FROM, to: DISPOSAL_TO, expect: 2 }
]) {
	const count = source.split(from).length - 1;
	if (count !== expect) {
		failures.push(`  ${id}: 期望 ${expect} 处，实际 ${count} 处`);
		continue;
	}
	if (to === null) {
		source = source.replace(from, `${INSERT_CODE}${from}`);
	} else {
		source = source.split(from).join(to);
	}
	applied += 1;
}

if (failures.length > 0) {
	process.stderr.write(`patch-tui-zh: ${failures.length} 项未命中，未写出任何文件：\n${failures.join("\n")}\n`);
	process.exit(1);
}

writeFileSync(output, source);
process.stdout.write(`patch-tui-zh: 已应用 ${applied} 项（替换 ${TABLE.length} + 插入 2），写出 ${output}\n`);
